package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateEmailException;

/**
 * Rejects creating an owner whose lower-cased email is already used by any other owner.
 * The request email and each existing owner's email are canonicalized via the shared
 * {@link OwnerEmails} rule (lower-cased) before comparing, so the check is independent of
 * the casing either value was supplied in. An absent/blank request email is never a
 * duplicate. A match is a 409 via {@link DuplicateEmailException}.
 */
public class EnsureUniqueOwnerEmail {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateEmailException {
        String email = OwnerEmails.normalize(request.getEmail());
        if (email == null || email.isBlank()) {
            return;
        }
        for (Owner existing : ownerRepository.findAll()) {
            if (email.equals(OwnerEmails.normalize(existing.getEmail()))) {
                throw new DuplicateEmailException(email);
            }
        }
    }
}
===== EnsureUniqueHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateHouseholdException;

/**
 * Rejects creating an owner when another owner already has the same last name and the
 * same address, compared case-insensitively with collapsed whitespace (see
 * {@link Households}). The request can opt out of the rule by setting
 * {@code sharesHousehold} true, in which case {@link AssignHousehold} joins the owner to
 * the shared household instead.
 */
public class EnsureUniqueHousehold {

    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
            throws DuplicateHouseholdException {
        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = Households.normalize(request.getLastName());
        String address = Households.normalizeAddress(request.getAddress());
        for (Owner existing : ownerRepository.findAll()) {
            if (Households.matches(existing, lastName, address)) {
                throw new DuplicateHouseholdException(request.getLastName(), request.getAddress());
            }
        }
    }
}
===== NormalizeOwnerTelephone =====
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;

/**
 * Normalizes the submitted telephone on create into E.164 form via {@link OwnerTelephones}.
 * The E.164 value is written back onto the request in place (the {@code @Val} object is
 * shared with later steps) so downstream steps store and return it; a number that cannot
 * form valid E.164 is rejected with 400 via {@link InvalidTelephoneException}.
 */
public class NormalizeOwnerTelephone {

    public void service(@Val OwnerFieldsDto request) throws InvalidTelephoneException {
        String telephone = request.getTelephone();
        String e164 = OwnerTelephones.toE164(telephone);
        if (e164 == null) {
            throw new InvalidTelephoneException(telephone);
        }
        request.setTelephone(e164);
    }
}
===== AssignHousehold =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.Locale;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;

/**
 * When the request sets {@code sharesHousehold} true, joins the new owner to the
 * household formed by owners that share the same last name and address, using the
 * shared comparison in {@link Households} so it cannot drift from the uniqueness check
 * that {@link EnsureUniqueHousehold} applied.
 *
 * <p>Every owner in a household carries the same {@code householdId} — a stable
 * identifier derived from the normalized last name and address, so all members
 * compute the same value independently. The new owner receives it, and any existing
 * household members that do not yet carry it are back-filled so the whole household
 * shares one identifier.
 *
 * <p>Does nothing when {@code sharesHousehold} is absent or false, leaving a solo
 * owner's {@code householdId} null.
 */
public class AssignHousehold {

    public void service(@Val OwnerFieldsDto request, @Val Owner owner, OwnerRepository ownerRepository) {
        if (!Boolean.TRUE.equals(request.getSharesHousehold())) {
            return;
        }
        String lastName = Households.normalize(owner.getLastName());
        String address = Households.normalizeAddress(owner.getAddress());
        String householdId = deriveHouseholdId(lastName, address);
        owner.setHouseholdId(householdId);
        for (Owner existing : ownerRepository.findAll()) {
            if (Households.matches(existing, lastName, address)
                    && !householdId.equals(existing.getHouseholdId())) {
                existing.setHouseholdId(householdId);
                ownerRepository.save(existing);
            }
        }
    }

    /** Stable identifier for a household: the first 12 upper-case hex characters of the
     *  SHA-256 of the normalized last name and address joined by a NUL separator. */
    private static String deriveHouseholdId(String lastName, String address) {
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256")
                    .digest((lastName + "\u0000" + address).getBytes(StandardCharsets.UTF_8));
            StringBuilder sb = new StringBuilder(digest.length * 2);
            for (byte b : digest) {
                sb.append(String.format("%02x", b));
            }
            return sb.substring(0, 12).toUpperCase(Locale.ROOT);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException("SHA-256 not available", ex);
        }
    }
}
===== Households =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Single source of truth for what a "household" is: two owners share one when their
 * last name and address match after normalization. The last name is trimmed, has runs
 * of whitespace collapsed to a single space and is lower-cased; the address uses the
 * canonical {@link OwnerAddresses} normalization (the same form that is stored and
 * returned), so the comparison always runs on the normalized address. Shared by
 * {@link EnsureUniqueHousehold} (which rejects an unintended duplicate) and
 * {@link AssignHousehold} (which joins an intended one), so the two steps cannot drift
 * apart: an owner admitted by one is matched by the other.
 */
final class Households {

    private Households() {
    }

    /** Lower-cases and collapses runs of whitespace to a single space so the comparison
     *  ignores case and incidental spacing differences. */
    static String normalize(String value) {
        if (value == null) {
            return "";
        }
        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
    }

    /** The canonical normalized address (see {@link OwnerAddresses}), used for every
     *  address comparison so it matches the stored and returned form. Never null. */
    static String normalizeAddress(String value) {
        String normalized = OwnerAddresses.normalize(value);
        return normalized == null ? "" : normalized;
    }

    /** Whether {@code existing} belongs to the household identified by the already
     *  normalized {@code lastName} and {@code address}. */
    static boolean matches(Owner existing, String normalizedLastName, String normalizedAddress) {
        return normalizedLastName.equals(normalize(existing.getLastName()))
                && normalizedAddress.equals(normalizeAddress(existing.getAddress()));
    }
}
===== OwnerTelephones =====
package org.springframework.samples.petclinic.rest.function.owner;

/**
 * Single source of truth for what a "normalized" owner telephone is: the number in
 * <a href="https://en.wikipedia.org/wiki/E.164">E.164</a> form. Used by
 * {@link NormalizeOwnerTelephone} when storing and by {@link EnsureUniqueOwnerTelephone}
 * when comparing against existing owners, so the rule cannot drift between the two steps.
 *
 * <p>The rule: spaces, dashes and brackets are stripped. If a leading {@code '+'} (and
 * therefore an explicit country code) is present it is kept; otherwise country code
 * {@code '+61'} is assumed and a single leading {@code '0'} is dropped from the national
 * digits. The result must have 8 to 15 digits after the {@code '+'}, and for a recognized
 * country code the national number must have the exact length that country requires
 * ({@code '+61'} => 9 national digits, {@code '+1'} => 10), else it is invalid.
 */
final class OwnerTelephones {

    private OwnerTelephones() {
    }

    /**
     * Returns the E.164 form of {@code telephone}, or {@code null} if it cannot form a
     * valid E.164 number (non-digit characters remaining, not 8-15 digits after the
     * {@code '+'}, or a wrong national-number length for a recognized country code).
     */
    static String toE164(String telephone) {
        if (telephone == null) {
            return null;
        }
        String trimmed = telephone.trim();
        boolean explicitCountryCode = trimmed.startsWith("+");
        // Strip spaces, dashes and brackets; keep a leading '+' and the digits.
        String stripped = trimmed.replaceAll("[\\s()\\-]", "");
        String digits = explicitCountryCode ? stripped.substring(1) : stripped;
        if (!digits.matches("\\d+")) {
            return null;
        }
        if (!explicitCountryCode) {
            // No country code: assume +61 and drop a single leading national '0'.
            if (digits.startsWith("0")) {
                digits = digits.substring(1);
            }
            digits = "61" + digits;
        }
        if (digits.length() < 8 || digits.length() > 15) {
            return null;
        }
        if (!hasValidNationalLength(digits)) {
            return null;
        }
        return "+" + digits;
    }

    /**
     * Checks the national-number length against the country code: {@code '+61'} requires
     * exactly 9 national digits and {@code '+1'} exactly 10. Unrecognized country codes are
     * accepted on the general 8-15 digit rule alone.
     */
    private static boolean hasValidNationalLength(String digits) {
        if (digits.startsWith("61")) {
            return digits.length() - 2 == 9;
        }
        if (digits.startsWith("1")) {
            return digits.length() - 1 == 10;
        }
        return true;
    }
}
===== OwnerEmails =====
package org.springframework.samples.petclinic.rest.function.owner;

import java.util.Locale;

/**
 * Single source of truth for what a "normalized" owner email is: lower-cased, so the
 * stored and returned value is canonical regardless of the casing the client sent.
 * Syntactic validity is enforced upstream by the {@code @Email} constraint on the
 * request DTO; this step only canonicalizes an already-valid (or absent) address.
 */
final class OwnerEmails {

    private OwnerEmails() {
    }

    static String normalize(String email) {
        return email == null ? null : email.toLowerCase(Locale.ROOT);
    }
}

